  S.a2=new Float32Array(N); S.b2=new Float32Array(N);
  for(let i=0;i<N;i++){ S.a[i]=1; S.b[i]=0; }
  const seeds=6+Math.round(hsh(1)*8);
  for(let s=0;s<seeds;s++){
    const cx=Math.floor(hsh(s*3+2)*GW), cy=Math.floor(hsh(s*3+3)*GH), rr=2+Math.floor(hsh(s*3+4)*3);
