}
const a=S.a,b=S.b,a2=S.a2,b2=S.b2,GN=GW*GH,buf=S.buf;

// ---- act-driven feed/kill drift (dramaturgy: patterns morph over minutes) ----
let feedC=clp(P.feed,0.01,0.09), killC=clp(P.kill,0.03,0.075);
const drift=K.t*0.02+K.section*0.6;
if(P.act==='mitosis'){ feedC=0.0367+0.004*Math.sin(drift); killC=0.0649+0.003*Math.cos(drift*0.8); }
else if(P.act==='bloom'){ feedC+=0.010*Math.sin(drift*0.7); killC+=0.006*Math.sin(drift*0.5+1.3); }
else { feedC+=0.006*Math.sin(drift*0.6); killC+=0.005*Math.cos(drift*0.45); }
feedC=clp(feedC,0.012,0.09); killC=clp(killC,0.03,0.073);
const Da=1.0, Db=0.5;

// ---- perpetual injector: keeps the sim from ever freezing (motion floor) ----
const injN=1+Math.round(dens*3);
for(let q=0;q<injN;q++){
  const ang=K.t*(0.23+q*0.11)+q*2.1, rad=0.28+0.16*Math.sin(K.t*0.07+q);
