  const iy=Math.floor((0.5+(P.y-0.5)*0.6+Math.sin(ang)*rad)*GH);
  const rr=1+Math.round(dens*2);
  const amp=0.55+A.bass*0.4;
  for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
    const x=((ix+dx)%GW+GW)%GW, y=((iy+dy)%GH+GH)%GH;
    if(dx*dx+dy*dy<=rr*rr){ const idx=y*GW+x; b[idx]=Math.min(1,b[idx]+amp*0.25); }
  }
}

