const fld=S.b;

// ---- palette + field->color mapping ----
const bgH=((P.hue%360)+360)%360;
const gain=1.2+en*2.6, thr=0.16;
const topo=style==='topo', neon=style==='neon', ink=style==='ink', therm=style==='thermal';
const bands=5+Math.round(dens*7);
buf.loadPixels(); const px=buf.pixels;
function hsb2rgb(h,s,v){h=((h%360)+360)%360;s/=100;v/=100;const c=v*s,xx=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,bl;const sg=Math.floor(h/60)%6;if(sg===0){r=c;g=xx;bl=0;}else if(sg===1){r=xx;g=c;bl=0;}else if(sg===2){r=0;g=c;bl=xx;}else if(sg===3){r=0;g=xx;bl=c;}else if(sg===4){r=xx;g=0;bl=c;}else{r=c;g=0;bl=xx;}return [(r+m)*255,(g+m)*255,(bl+m)*255];}
